package com.sami.app.sales.receipt;
import com.sami.app.accounting.publicapi.ReceivableSettlementPort; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.common.exception.*; import com.sami.app.organization.service.OrganizationScopeService; import com.sami.app.organization.service.FoundationAuditService; import com.sami.app.treasury.service.TreasuryService; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class ReceiptConfirmationOrchestrator { private final JdbcTemplate jdbc; private final TenantContext tenants; private final TreasuryService treasury; private final Optional<ReceivableSettlementPort> settlement; private final OrganizationScopeService scope; private final FoundationAuditService audit;
 @Transactional public Map<String,Object> confirm(Long id,Long treasuryAccountId){Long t=tenants.requireTenantId(); if(treasuryAccountId!=null)jdbc.update("update sales_receipts set treasury_account_id=? where tenant_id=? and id=? and status='DRAFT'",treasuryAccountId,t,id); Map<String,Object> r=jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=? for update",t,id); if("CONFIRMED".equals(r.get("status")))return r; Long account=(Long)r.get("treasury_account_id"),company=(Long)r.get("company_id"),branch=(Long)r.get("branch_id"),customer=(Long)r.get("customer_id"); scope.requireScope(company,branch); if(account==null||jdbc.queryForObject("select count(*) from treasury_accounts where id=? and tenant_id=? and company_id=? and branch_id=? and active=true",Long.class,account,t,company,branch)!=1)throw new ApiException(ErrorCode.ACCESS_DENIED,"Treasury account is outside the authorized scope"); if(settlement.isEmpty())throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Accounting settlement provider is unavailable"); BigDecimal allocated=jdbc.queryForObject("select coalesce(sum(amount),0) from sales_receipt_allocations where tenant_id=? and receipt_id=?",BigDecimal.class,t,id); if(allocated==null||allocated.signum()<=0||allocated.compareTo((BigDecimal)r.get("amount"))>0)throw new ApiException(ErrorCode.VALIDATION_FAILED,"Receipt allocations are invalid"); Boolean owned=jdbc.queryForObject("select not exists(select 1 from sales_receipt_allocations a join sales_invoices i on i.id=a.sales_invoice_id where a.tenant_id=? and a.receipt_id=? and (i.tenant_id<>? or i.company_id<>? or i.branch_id<>? or i.customer_id<>? or i.status<>'ISSUED'))",Boolean.class,t,id,t,company,branch,customer); if(!Boolean.TRUE.equals(owned))throw new ApiException(ErrorCode.ACCESS_DENIED,"Invoice allocation is outside the authorized scope"); Long tx=treasury.recordInflow(account,(BigDecimal)r.get("amount"),Instant.now(),"sales-receipt",String.valueOf(r.get("receipt_number")),"Customer receipt"); audit.record(t,company,branch,"SALES_RECEIPT",id,"TREASURY_INFLOW",null,Map.of("transactionId",tx)); String posting=settlement.get().settle(new ReceivableSettlementPort.ReceiptSettlementCommand(t,company,branch,customer,null,(BigDecimal)r.get("amount"),"IRR",Instant.now(),"SALES-RECEIPT-"+t+"-"+id)); audit.record(t,company,branch,"SALES_RECEIPT",id,"ACCOUNTING_SETTLEMENT",null,Map.of("postingReference",posting)); jdbc.update("update sales_receipts set treasury_transaction_id=?,accounting_posting_reference=?,status='CONFIRMED',confirmed_at=now(),version=version+1 where tenant_id=? and id=?",tx,posting,t,id); audit.record(t,company,branch,"SALES_RECEIPT",id,"RECEIPT_CONFIRMED",null,Map.of("treasuryTransactionId",tx,"postingReference",posting,"allocated",allocated)); return jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=?",t,id); }
}
